#!/usr/bin/python3
import json,time,socket,threading,urllib.request
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
NODES=json.loads(Path('/etc/mariadb-lab-monitor/nodes.json').read_text())
state={'updated':None,'nodes':[]}
def check(node):
    result={**node,'status':'red','reason':'Node unavailable'}
    try:
        if node['role']=='maxscale':
            with socket.create_connection((node['ip'],3306),timeout=3): pass
            result.update(status='green',reason='Proxy listener reachable (TCP check)')
        else:
            with urllib.request.urlopen('http://'+node['ip']+':9109/health',timeout=7) as response:
                health=json.load(response)
            result['details']=health
            if not health.get('reachable'): return result
            channels=health.get('channels',[])
            if node['role']=='primary':
                result.update(status='green' if health['read_only']=='0' else 'red',reason='Writable primary' if health['read_only']=='0' else 'Primary is read only')
            elif not channels:
                result['reason']='Replication channel missing'
            elif any(c.get('Slave_IO_Running')!='Yes' or c.get('Slave_SQL_Running')!='Yes' or c.get('Seconds_Behind_Master') in (None,'NULL') or c.get('Last_IO_Errno','0')!='0' or c.get('Last_SQL_Errno','0')!='0' for c in channels):
                result['reason']='Replication stopped, disconnected or reporting errors'
            else:
                lag=max(int(c['Seconds_Behind_Master']) for c in channels)
                result.update(status='amber' if lag>0 else 'green',reason=f'Replication lag: {lag}s',lag=lag)
    except Exception:
        pass
    return result

def poll():
    global state
    while True:
        with ThreadPoolExecutor(max_workers=8) as pool: rows=list(pool.map(check,NODES))
        state={'updated':time.time(),'nodes':rows}
        time.sleep(10)

PAGE='<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MariaDB replication topology</title>\n<style>\n*{box-sizing:border-box}body{margin:0;background:#f5f6fa;color:#172033;font:15px system-ui}header{margin:20px;padding:22px;background:white;border:1px solid #e0e4eb;border-radius:14px;display:flex;justify-content:space-between;align-items:center;gap:20px}h1{font-size:25px;margin:0 0 5px}small,.muted{color:#657187}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:13px}.dot{width:10px;height:10px;border-radius:50%;display:inline-block;margin-right:5px}.canvas{position:relative;margin:20px;height:calc(100vh - 170px);min-height:480px;border:1px solid #e0e4eb;border-radius:14px;background:white;overflow:hidden}svg{width:100%;height:100%;touch-action:none;cursor:grab}svg:active{cursor:grabbing}.controls{position:absolute;left:20px;bottom:20px;display:flex;flex-direction:column;gap:3px}button{background:white;border:1px solid #d6dce7;border-radius:6px;padding:9px 13px;color:#27354a;cursor:pointer;font:inherit}button:hover{background:#edf2f9}.notice{position:absolute;left:20px;top:16px;color:#657187;font-size:13px}.details{position:absolute;right:18px;top:18px;width:350px;max-width:calc(100% - 36px);max-height:calc(100% - 36px);overflow:auto;background:white;padding:20px;border:1px solid #d6dce7;border-radius:12px;box-shadow:0 8px 32px #17203320;display:none}.details pre{font:12px ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.details h2{margin-top:0}.node{cursor:pointer}.node:hover rect{filter:brightness(.92)}.summary{font-size:13px;margin-top:8px}@media(max-width:700px){header{align-items:flex-start;flex-direction:column;margin:12px;padding:16px}.canvas{margin:12px;height:70vh}.legend{gap:9px}}\n</style></head><body>\n<header><div><h1>MariaDB lab</h1><small>Primary and replica topology · live database health</small><div id="stamp" class="summary">Waiting for first health check…</div></div><div class="legend"><span><i class="dot" style="background:#168347"></i>Healthy</span><span><i class="dot" style="background:#d18b08"></i>Lagging</span><span><i class="dot" style="background:#d33e43"></i>Unhealthy</span></div></header>\n<div class="canvas"><div class="notice">Drag to pan · scroll to zoom · click a server for details</div><svg id="graph" role="img" aria-label="Live MariaDB replication topology"><g id="viewport"></g></svg><div class="controls"><button id="plus" aria-label="Zoom in">+</button><button id="minus" aria-label="Zoom out">−</button><button id="fit">Fit</button></div><aside class="details" id="detail"><button id="close" style="float:right">Close</button><h2 id="name"></h2><p id="reason"></p><pre id="data"></pre></aside></div>\n<script>\nconst svg=document.getElementById(\'graph\'),view=document.getElementById(\'viewport\');const ns=\'http://www.w3.org/2000/svg\';let scale=1,tx=0,ty=0,drag=null,extent={w:1000,h:600},first=true,lastData=null,connectionLost=false;\nfunction el(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e}\nfunction transform(){view.setAttribute(\'transform\',`translate(${tx},${ty}) scale(${scale})`)}\nfunction fit(){const box=svg.getBoundingClientRect();scale=Math.min((box.width-70)/extent.w,(box.height-100)/extent.h,1.4);tx=(box.width-extent.w*scale)/2;ty=(box.height-extent.h*scale)/2+20;transform()}\nfunction zoom(f,x,y){const next=Math.max(.12,Math.min(3,scale*f));tx=x-(x-tx)*next/scale;ty=y-(y-ty)*next/scale;scale=next;transform()}\nsvg.addEventListener(\'wheel\',e=>{e.preventDefault();const b=svg.getBoundingClientRect();zoom(e.deltaY<0?1.12:1/1.12,e.clientX-b.left,e.clientY-b.top)},{passive:false});svg.addEventListener(\'pointerdown\',e=>{if(e.target.closest(\'.node\'))return;drag={x:e.clientX,y:e.clientY,tx,ty};svg.setPointerCapture(e.pointerId)});svg.addEventListener(\'pointermove\',e=>{if(drag){tx=drag.tx+e.clientX-drag.x;ty=drag.ty+e.clientY-drag.y;transform()}});svg.addEventListener(\'pointerup\',()=>drag=null);svg.addEventListener(\'pointercancel\',()=>drag=null);\nfor(const [id,f] of [[\'plus\',1.25],[\'minus\',.8]])document.getElementById(id).onclick=()=>{const b=svg.getBoundingClientRect();zoom(f,b.width/2,b.height/2)};document.getElementById(\'fit\').onclick=fit;document.getElementById(\'close\').onclick=()=>document.getElementById(\'detail\').style.display=\'none\';window.addEventListener(\'resize\',fit);\nfunction show(n,stale){document.getElementById(\'detail\').style.display=\'block\';document.getElementById(\'name\').textContent=n.name;document.getElementById(\'reason\').textContent=stale?\'Monitoring results stale\':n.reason;document.getElementById(\'data\').textContent=JSON.stringify(n.details||{ip:n.ip,check:n.reason},null,2)}\nfunction draw(d){lastData=d;view.replaceChildren();const stale=connectionLost||!d.updated||Date.now()/1000-d.updated>35;const nodes=d.nodes||[],db=nodes.filter(n=>n.role!==\'maxscale\'),proxy=nodes.filter(n=>n.role===\'maxscale\');const primary=db.find(n=>n.role===\'primary\');const replicas=db.filter(n=>n.role!==\'primary\').sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));const byIP=new Map(db.map(n=>[n.ip,n]));const parents=new Map();for(const n of replicas){const channels=n.details?.channels||[];const sources=channels.map(c=>byIP.get(c.Master_Host)).filter(Boolean);parents.set(n.name,sources.length?sources:primary?[primary]:[])}\nconst level=new Map();if(primary)level.set(primary.name,0);function depth(n,seen=new Set()){if(level.has(n.name))return level.get(n.name);if(seen.has(n.name))return 1;seen.add(n.name);const ps=parents.get(n.name)||[];const v=Math.min(8,ps.length?1+Math.max(...ps.map(p=>depth(p,new Set(seen)))):1);level.set(n.name,v);return v}replicas.forEach(n=>depth(n));const rows=new Map();for(const n of db){const l=level.get(n.name)||0;if(!rows.has(l))rows.set(l,[]);rows.get(l).push(n)}\nconst widest=Math.max(1,...[...rows.values()].map(r=>r.length),proxy.length),width=Math.max(760,widest*240),positions=new Map();for(const [l,row]of rows){row.forEach((n,i)=>positions.set(n.name,{x:width/2+(i-(row.length-1)/2)*240-100,y:100+l*190}))}const bottom=100+(Math.max(0,...rows.keys())+1)*190;proxy.forEach((n,i)=>positions.set(n.name,{x:width/2+(i-(proxy.length-1)/2)*240-100,y:bottom+35}));extent={w:width,h:bottom+(proxy.length?180:30)};\nfor(const n of replicas){const target=positions.get(n.name);for(const p of parents.get(n.name)||[]){const source=positions.get(p.name);if(!source||!target)continue;const reported=(n.details?.channels||[]).some(c=>byIP.get(c.Master_Host)?.name===p.name);const y=(source.y+90+target.y)/2;el(\'path\',{d:`M ${source.x+100} ${source.y+90} V ${y} H ${target.x+100} V ${target.y}`,fill:\'none\',stroke:\'#99a4b6\',\'stroke-width\':1.8,\'stroke-dasharray\':reported?\'\':\'6 5\'},view)}}\nfor(const n of nodes){const p=positions.get(n.name);if(!p)continue;const status=stale?\'red\':n.status,color={green:\'#168347\',amber:\'#d18b08\',red:\'#d33e43\'}[status]||\'#d33e43\';const g=el(\'g\',{class:\'node\',transform:`translate(${p.x},${p.y})`,tabindex:0,role:\'button\',\'aria-label\':`${n.name}: ${stale?\'stale\':n.reason}`},view);el(\'rect\',{width:200,height:90,rx:8,fill:color,stroke:\'#183024\',\'stroke-width\':2},g);const text=[n.name,n.ip,n.role===\'maxscale\'?\'PROXY · TCP CHECK\':n.role===\'primary\'?\'PRIMARY\':`REPLICA · ${n.lag!==undefined?n.lag+\'s lag\':status.toUpperCase()}`];text.forEach((t,i)=>{const e=el(\'text\',{x:100,y:25+i*22,\'text-anchor\':\'middle\',fill:\'white\',\'font-size\':i===0?15:12,\'font-weight\':i===0?700:400},g);e.textContent=t});g.onclick=()=>show(n,stale);g.onkeydown=e=>{if(e.key===\'Enter\'||e.key===\' \'){e.preventDefault();show(n,stale)}}}\nconst stamp=document.getElementById(\'stamp\');stamp.textContent=stale?\'Monitoring stale / unavailable — all nodes shown red\':`Last check: ${new Date(d.updated*1000).toLocaleTimeString()} · ${db.length} database nodes · dashed links = expected topology, not confirmed`;if(first&&nodes.length){fit();first=false}else transform()}\nasync function refresh(){try{const r=await fetch(\'/api/health\',{cache:\'no-store\'});if(!r.ok)throw Error();const d=await r.json();connectionLost=false;draw(d)}catch(e){connectionLost=true;if(lastData)draw(lastData);else document.getElementById(\'stamp\').textContent=\'Dashboard connection unavailable\'}}refresh();setInterval(refresh,5000);\n</script></body></html>\n'

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path=='/api/health': data=json.dumps(state).encode(); kind='application/json'
        elif self.path=='/': data=PAGE.encode(); kind='text/html; charset=utf-8'
        else: self.send_error(404);return
        self.send_response(200);self.send_header('Content-Type',kind);self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(data)
    def log_message(self,*args):pass
if __name__=='__main__':
    threading.Thread(target=poll,daemon=True).start()
    ThreadingHTTPServer(('127.0.0.1',8081),Handler).serve_forever()
